import{_ as t,I as o,g as a,j as s}from"./chunks/framework.Ha9mtr6N.js";const p=JSON.parse('{"title":"Finished Goods (Showcase)","description":"Warehouse management of finished products, stock inventory adjustments, and FIFO cost pricing in OmniCraft ERP.","frontmatter":{"title":"Finished Goods (Showcase)","description":"Warehouse management of finished products, stock inventory adjustments, and FIFO cost pricing in OmniCraft ERP.","order":8},"headers":[],"relativePath":"docs/spaces/production/showcase.md","filePath":"docs/spaces/production/showcase.md"}'),r={name:"docs/spaces/production/showcase.md"};function i(n,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🛒-finished-goods-the-showcase-showroom-inventory" tabindex="-1">🛒 Finished Goods: The Showcase &amp; Showroom Inventory <a class="header-anchor" href="#🛒-finished-goods-the-showcase-showroom-inventory" aria-label="Permalink to &quot;🛒 Finished Goods: The Showcase &amp; Showroom Inventory&quot;">​</a></h1><p>The <strong>&quot;Finished Goods&quot;</strong> tab is your digital showcase. It displays the active physical balances of all your manufactured items, their current cost price, and the recommended retail price.</p><p>Products do not appear here out of thin air. For an item to appear on your showcase, it must pass through the <a href="./workbench">In Production</a> tab (i.e., be completed on the Workbench).</p><hr><h2 id="📋-the-product-card" tabindex="-1">📋 The Product Card <a class="header-anchor" href="#📋-the-product-card" aria-label="Permalink to &quot;📋 The Product Card&quot;">​</a></h2><p>Each product is presented as a clean card containing all crucial inventory metrics:</p><ul><li><strong>In Stock:</strong> The active physical balance in your showroom.</li><li><strong>Total Manufactured:</strong> A historical counter (how many units of this product you have crafted over your entire history in the program).</li><li><strong>Recommended Retail Price (RRP):</strong> The price automatically computed by the software based on your cost price and global markup (configured in Settings).</li></ul><h3 id="dual-cost-pricing-calculated-vs-actual-stock-cost" tabindex="-1">Dual Cost Pricing (Calculated vs. Actual Stock Cost) <a class="header-anchor" href="#dual-cost-pricing-calculated-vs-actual-stock-cost" aria-label="Permalink to &quot;Dual Cost Pricing (Calculated vs. Actual Stock Cost)&quot;">​</a></h3><p>If you have an item in stock, its card displays two distinct cost price values:</p><ol><li><strong>Calculated Cost Price:</strong> The <em>theoretical</em> cost of manufacturing the item right now using your current raw material warehouse stock.</li><li><strong>Actual Stock Cost Price:</strong> The <em>actual</em> cost price of the specific units currently sitting on your shelf. It is retrieved directly from the exact batches you physically completed earlier.</li></ol><div class="info custom-block"><p class="custom-block-title">Why Use Two Cost Prices? (The FIFO Method)</p><p>Suppose you crafted a bag a month ago when leather was cheaper. The cost price of that bag was <code>$300</code>. The bag was placed on your showroom shelf. Today, leather has significantly increased in price. The Calculator shows that crafting an identical bag right now costs <code>$500</code>. If the program simply updated the cost price of your older bag to <code>$500</code>, your reported profit margins upon sale would be heavily distorted. OmniCraft ERP does not do this. The program remembers that the old <code>$300</code> bag is sitting on the shelf and will deduct exactly that figure when it is sold, ensuring cost-accounting accuracy for your net profit. This is called the <strong>FIFO (First In, First Out)</strong> method.</p></div><hr><h2 id="⚖️-finished-goods-inventory-adjustments" tabindex="-1">⚖️ Finished Goods Inventory Adjustments <a class="header-anchor" href="#⚖️-finished-goods-inventory-adjustments" aria-label="Permalink to &quot;⚖️ Finished Goods Inventory Adjustments&quot;">​</a></h2><p>Just like in the raw materials warehouse, physical reality can sometimes diverge from the software data (e.g., you gifted a wallet to a friend and forgot to log it, or you found a keychain on a shelf that was never completed on the Workbench).</p><p>To correct these discrepancies, every product card features an <strong>&quot;Inventory Adjustment&quot;</strong> button.</p><ol><li>Select the adjustment type: <strong>Record Surplus (+)</strong> or <strong>Record Loss (-)</strong>.</li><li>Specify the quantity.</li><li>Click &quot;Save&quot;.</li></ol><h3 id="how-inventory-adjustments-affect-your-finances" tabindex="-1">How Inventory Adjustments Affect Your Finances <a class="header-anchor" href="#how-inventory-adjustments-affect-your-finances" aria-label="Permalink to &quot;How Inventory Adjustments Affect Your Finances&quot;">​</a></h3><p>Finished goods inventory adjustments <strong>do not impact your Cash Flow ledger</strong>.</p><ul><li>When writing off a loss, the program simply removes the oldest batches (using FIFO) from showroom stock. No money is deducted from your Cash Flow Ledger, as this is purely an inventory correction.</li><li>When recording a surplus, the program adds the item to your showroom shelf and assigns it the <em>current calculated cost price</em> from the Calculator.</li></ul><div class="warning custom-block"><p class="custom-block-title">Do Not Use Inventory Adjustments for Sales!</p><p>Writing off a loss simply removes the product from stock without generating revenue. If you gave an item to a client, always process it through the <strong>Sales</strong> tab, even if you provided a 100% discount. In that case, simply process the sale with a price of <code>$0</code> so that the program accurately logs the cost price of that item as an operational loss.</p></div>',21)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
